import clr
from System import *
# INICIO SCRIPT USUARIO
CNPJ = FormularioRegistro["CNPJ"].Valor
CNPJ2 = CNPJ
if (CNPJ != None) :
	if (len(CNPJ) != 14) : 
		FormularioRegistro["CNPJ"].Valor = None
		Formulario.ExibeMensagem("No CNPJ digite apenas os 14 números")
	else:
		if (Convert.ToString(CNPJ2).isdigit() != True) :
			FormularioRegistro["CNPJ"].Valor = None
			Formulario.ExibeMensagem("No CNPJ digite apenas os números")
		else :
			FormularioRegistro["CNPJ"].Valor = CNPJ2[0:2]+"."+CNPJ2[2:5]+"."+CNPJ2[5:8]+"/"+CNPJ2[8:12]+"-"+CNPJ2[12:14]

