if (CNPJ != None) :
	if (len(CNPJ) != 14) : 
		FormularioRegistro["CNPJ"].Valor = None
		Formulario.ExibeMensagem("No CNPJ digite apenas os 14 números")
	else:
		if (Convert.ToString(CNPJ2).isdigit() != True) :
