CustomProperty.Description:
Para pesquisa rápida faça:
1 - Clique na seta à direita do campo para abrir a relação de nomes;
2 - Com a lista ABERTA, pressione as teclas Ctrl + F (no IE aparece uma caixa de texto na parte superior esquerda e no Chrome na parte superior direita);
3 -  Digite o nome (ou parte dele) a ser pesquisado (serão marcados todas ocorrências que correspondam ao texto digitado);

CustomProperty.LookupScript:
import clr
from System import *
# INICIO SCRIPT USUARIO
###PGESV###

lista = DB.ExecuteDataTable("select ch3, vl1 from sv_param where ch1 = 'GESTORES_RESPONSA' order by ch1,ch2")

sv_param_pai = None
sv_param_filho = None
for l in lista.Rows:
    if l["CH3"] == "ORGAO_PAI":
       if sv_param_pai == None:
          sv_param_pai = "(orgao_pai.descricao like '" + l["vl1"] + "'"
       else:
          sv_param_pai += " OR orgao_pai.descricao like '" + l["vl1"] + "'"
    elif l["CH3"] == "ORGAO_FILHO":
       if sv_param_filho == None:
          sv_param_filho = "(orgao_filho.descricao not like '" + l["vl1"] + "'"
       else:
          sv_param_filho += " AND orgao_filho.descricao not like '" + l["vl1"] + "'"
          
if sv_param_pai == None:
   sv_param_pai += " 1 <> 1 " # faltam dados na tabela sv_param
else:
   sv_param_pai += ") "

if sv_param_filho == None:
   sv_param_filho += " 1 <> 1 " # faltam dados na tabela sv_param
else:
   sv_param_filho += ") "
   
Itens = DB.ExecuteDataTable("SELECT TO_CHAR(ORGAO_FILHO.ID_ORGAO) AS id_orgao,'('|| cobra_hierarquia.scr_sigla|| ') '|| ORGAO_FILHO.descricao area FROM orgao orgao_filho JOIN orgao orgao_pai ON (orgao_filho.id_orgao_pai = orgao_pai.id_orgao) JOIN cobra_hierarquia ON (orgao_filho.sigla = cobra_hierarquia.scr) WHERE (" + sv_param_pai.ToString() + ") AND orgao_filho.ativo LIKE 'Sim' AND " + sv_param_filho.ToString() + " ORDER BY ORGAO_FILHO.DESCRICAO")

RecordColumn.LookupScript:
import clr from System import * clr.AddReference('Supravizio.Custom') from Venki.Supravizio.Processo.Custom import OrdemServico # INICIO SCRIPT USUARIO idFavorecido = OrdemServico.GetCustom("FAVORECIDO_COBRA")
#if idFavorecido != None: # Itens = DB.ExecuteDataTable(" SELECT DISTINCT DEP.NOME_DEPENDENTE FROM DEPENDENTES_BENEFICIOS_V DEP INNER JOIN CAD_FUNCIONARIO_V FU ON DEP.MATRICULA = FU.MATRICULA INNER JOIN PESSOA PE ON PE.NOME = FU.NOME WHERE pe.ID_PESSOA = "+ idFavorecido.ToString() +" AND dep.beneficio = 'REEMBOLSO FARMACIA' ORDER BY DEP.NOME_DEPENDENTE ")
if OrdemServico.GetCustom("FAVORECIDO_COBRA").ToString() != "": Itens = DB.ExecuteDataTable(" SELECT DISTINCT DEP.NOME_DEPENDENTE FROM DEPENDENTES_BENEFICIOS_V DEP INNER JOIN CAD_FUNCIONARIO_V FU ON DEP.MATRICULA = FU.MATRICULA INNER JOIN PESSOA PE ON PE.NOME = FU.NOME WHERE pe.ID_PESSOA = "+ OrdemServico.GetCustom("FAVORECIDO_COBRA").ToString() +" and dep.nome_dependente <> ' ' AND dep.beneficio = 'REEMBOLSO FARMACIA' ORDER BY DEP.NOME_DEPENDENTE ")

