import clr from System import * # INICIO SCRIPT USUARIO sqlValor = "select distinct cnpj , FORNECEDOR || ' - ' || cnpj as FORNECEDOR from fornecedor_compras where status = 'Ativo' and cnpj= '"+ValorCorrente+"'"
sqlEntrada = "select distinct cnpj , FORNECEDOR || ' - ' || cnpj as FORNECEDOR from fornecedor_compras where status = 'Ativo' AND UPPER(FORNECEDOR) like UPPER('%"+EntradaUsuario+"%')"
sqlOrder = " order by FORNECEDOR asc"
if not String.IsNullOrEmpty(ValorCorrente) and not String.IsNullOrEmpty(EntradaUsuario):
Itens = DB.ExecuteDataTable("(" + sqlValor + ") UNION (" + sqlEntrada + " ) " + sqlOrder)
elif String.IsNullOrEmpty(EntradaUsuario) and String.IsNullOrEmpty(ValorCorrente):
#Itens = DB.ExecuteDataTable( sqlEntrada + sqlOrder) None
elif String.IsNullOrEmpty(EntradaUsuario):
Itens = DB.ExecuteDataTable( sqlValor + sqlOrder)
else:
Itens = DB.ExecuteDataTable( sqlEntrada + sqlOrder)

