import clr from System import * clr.AddReference('Supravizio.Custom') from Venki.Supravizio.Recurso.Custom import Orgao from Venki.Supravizio.Processo.Custom import OrdemServico # INICIO SCRIPT USUARIO pessoa = OrdemServico.Cliente orgao = Orgao.Carrega(pessoa.OrgaoId)
executivo = None diretor = None exceto = "'3000003252', '3000003242', '3000003241', '3000003247'" exceto1 = "'ESTAGIARIO','JOVEM APRENDIZ','PRESTADOR DE SERVICO'" qry = "" # 1 - encontrar executivo e diretor - teste ok while (pessoa["CARGO_FUNCIONAL"].Contains("DIRETOR") == False and pessoa["CARGO_FUNCIONAL"].Contains("PRESIDENTE") == False and pessoa != pessoa.ObtemChefia(True)): #Formulario.ExibeMensagem(pessoa["CARGO_FUNCIONAL"]) if pessoa["CARGO_FUNCIONAL"].Contains("EXECUTIVO"): executivo = pessoa pessoa = pessoa.ObtemChefia(True) # # verifica se encontrou diretor ou presidente if pessoa["CARGO_FUNCIONAL"].Contains("DIRETOR") or pessoa["CARGO_FUNCIONAL"].Contains("PRESIDENTE"): diretor = pessoa
if executivo != None: uorsSub = executivo.Orgao.ObtemSubOrgaos(True) uors = "'" + orgao.Sigla.ToString() + "'" for uor in uorsSub: if not exceto.Contains(uor.Sigla): if uor.Ativo and not String.IsNullOrEmpty(uor.Sigla): if uors != "": uors += ", " uors += "'" + uor.Sigla + "'" uorexe = executivo.Orgao.Sigla qry = "SELECT to_char(P.ID_PESSOA), (nome || ' (' || cp.matricula || ')') nome FROM PESSOA P INNER JOIN ORGAO O ON (P.ID_ORGAO = O.ID_ORGAO) inner join cp_pessoa cp on (p.id_pessoa = cp.id_pessoa ) WHERE p.Ativo ='Sim' and (O.SIGLA IN(" + uors + ") or O.SIGLA IN (" + uorexe +")) and cp.cargo_funcional is not null and cp.cargo_funcional not in (" + exceto1 + ") order by nome"
if qry != "": Itens = DB.ExecuteDataTable(qry)

import clr
from System import *
clr.AddReference('Supravizio.Custom')
from Venki.Supravizio.Recurso.Custom import Orgao
from Venki.Supravizio.Processo.Custom import OrdemServico
# INICIO SCRIPT USUARIO
pessoa = OrdemServico.Cliente
orgao = Orgao.Carrega(pessoa.OrgaoId)
#uors = "'" + orgao.Sigla.ToString() + "'"

executivo = None
uorsExecutivo = ""
uorsAudit = "'4000001110', '4000001111', '4000001112'"

diretor = None
exceto = "'3000003252', '3000003242', '3000003241', '3000003247'"
exceto1 = "'ESTAGIARIO','JOVEM APRENDIZ','PRESTADOR DE SERVICO'"
qry = ""
# 1 - encontrar executivo e diretor
while (pessoa["CARGO_FUNCIONAL"].Contains("DIRETOR") == False and pessoa["CARGO_FUNCIONAL"].Contains("PRESIDENTE") == False and pessoa != pessoa.ObtemChefia(True)):
      if pessoa["CARGO_FUNCIONAL"].Contains("EXECUTIVO"):
         executivo = pessoa
      pessoa = pessoa.ObtemChefia(True)
#
# verifica se encontrou diretor ou presidente

if pessoa["CARGO_FUNCIONAL"].Contains("DIRETOR") or pessoa["CARGO_FUNCIONAL"].Contains("PRESIDENTE"):
   diretor = pessoa

if executivo != None:
   uorsSub = executivo.Orgao.ObtemSubOrgaos(True)
   #uors = "'" + orgao.Sigla.ToString() + "'"
   for uor in uorsSub:
       if not exceto.Contains(uor.Sigla):
          if uor.Ativo and not String.IsNullOrEmpty(uor.Sigla):
             if uorsExecutivo != "":
                uorsExecutivo += ", "
             uorsExecutivo += "'" + uor.Sigla + "'"
             
if diretor != None:
   uorsSub = diretor.Orgao.ObtemSubOrgaos(True)
   uors = ""
   for uor in uorsSub:
       if not (exceto.Contains(uor.Sigla) or uorsExecutivo.Contains(uor.Sigla)):
          if uor.Ativo and not String.IsNullOrEmpty(uor.Sigla):
             if uors != "":
                uors += ", "
             uors += "'" + uor.Sigla + "'"

# TRATAR AUDITORIA             
if uorsAudit.Contains(orgao.Sigla):
   uors += uorsAudit.Replace(orgao.Sigla, "")
   
qry = "SELECT to_char(P.ID_PESSOA), (nome || ' (' || cp.matricula || ')') nome FROM PESSOA P INNER JOIN ORGAO O ON (P.ID_ORGAO = O.ID_ORGAO) inner join cp_pessoa cp on (p.id_pessoa = cp.id_pessoa ) WHERE p.Ativo ='Sim' and O.SIGLA IN(" + uors + ") and cp.cargo_funcional is not null and cp.cargo_funcional not in (" + exceto1 + ") ORDER BY NOME"
   
if qry != "":
   Itens = DB.ExecuteDataTable(qry)

