ScriptModule.Source:
def PrecifObtemCronogramaAtividade(ID_OCORRENCIA, CODIGO_ATIVIDADE):
    qry = " SELECT ID_OCORRENCIA, CODIGO_ATIVIDADE, RESPONSAVEL_ATIVIDADE, DATA_INICIO_ATIVIDADE, DATA_FIM_ATIVIDADE, DIAS_ATIVIDADE FROM Z_00143_PRECIF_CRONOGRAMA WHERE ID_OCORRENCIA = " + ID_OCORRENCIA.ToString() + " AND CODIGO_ATIVIDADE = '" + CODIGO_ATIVIDADE.ToString() + "'"

    lista = DB.ExecuteDataTable(qry)

    for linha in lista.Rows:
        return linha

def cronograma_dod_itera_sub(ID_OCORRENCIA, FASE):

    qry = " SELECT nvl(MAX(ITERACAO),0) ITERACAO FROM CRONOGRAMA_DOD WHERE ID_OCORRENCIA = "  + ID_OCORRENCIA.ToString() + " AND FASE = " + FASE.ToString() + ""
    
    #OrdemServico.AdicionaComentario(" cronograma_dod_iteracao - " + qry  , False) 

    lista = DB.ExecuteDataTable(qry)

    for linha in lista.Rows:
        return linha["ITERACAO"]

def ValidaItensAdm():
    if OrdemServico["PRJ_TIPO_SOLICITACAO"] == "Cadastrar" and String.IsNullOrEmpty(OrdemServico["PRJ_DESC_ITEM"]):
