def tabela_servico_subprocesso(tipoServico):
qry = " SELECT DISTINCT S.Sigla AS SIGLA_SERVICO, S.Descricao AS DESC_SERVICO FROM Rest_Servico RS INNER JOIN Classe_Sub_Processo CSP ON Rs.Id_Classe_Sub_Processo = Csp.Id_Classe_Sub_Processo INNER JOIN Servico S ON Rs.Id_Servico = S.Id_Servico INNER JOIN Sub_Processo SP ON Sp.Id_Classe_Sub_Processo = Csp.Id_Classe_Sub_Processo INNER JOIN Desenho_Processo DP ON Dp.Id_Desenho_Processo = Sp.Id_Desenho_Processo INNER JOIN Processo PR ON PR.Id_Processo = Dp.Id_Processo INNER JOIN macro_processo mp ON mp.id_macro_processo = pr.id_macro_processo inner join Classe_Servico CS on Cs.Id_Classe_Servico = S.Id_Classe_Servico AND mp.DESCRICAO = 'Tecnologia da Informação Empresarial' WHERE Csp.Sigla = 'INCISISTE' And s.ativo = 'Sim' and Cs.Sigla = '" + tipoServico.ToString() + "' ORDER BY S.Descricao"
servicos = DB.ExecuteDataTable(qry)
return servicos.ToString()

def PCMSOVerificaNovoAtestado(matricula, idOcorrencia):
    
    valor = 0
     
    valor = DB.ExecuteScalar(" SELECT COUNT(a.emplid) FROM ps_gp_abs_event a, ps_GP_PIN b, PS_GP_ABS_RSN_LANG C, PS_GP_ABS_TAKE d, PS_GPBR_ABS_EV_AI e, ps_BBTS_APOSENTADO f, Pessoa g, cp_Pessoa h, Orgao i WHERE a.emplid = e.emplid AND a.pin_TAKE_num = e.pin_TAKE_num AND a.bgn_dt = e.bgn_dt AND a.end_dt = e.end_dt AND a.pin_TAKE_num = b.pin_num  AND a.pin_TAKE_num   = d.pin_num AND d.ABS_TYPE_OPTN = c.ABS_TYPE_OPTN AND A.ABSENCE_REASON = C.ABSENCE_REASON AND G.Id_Pessoa = H.Id_Pessoa  AND A.Emplid = h.matricula AND I.Id_Orgao = G.Id_Orgao AND c.country = 'BRA' AND c.language_cd = 'POR' AND a.emplid = f.emplid (+) AND b.pin_num IN ('220245', '220250') AND c.effdt = (SELECT MAX(cc.effdt) FROM PS_GP_ABS_RSN_LANG cc WHERE c.country = cc.country AND c.absence_reason = cc.absence_reason AND c.abs_type_optn = cc.abs_type_optn AND c.language_cd = cc.language_cd ) and A.END_DT > (Select  MAX(at.data_fim) From  Z_00143_PCMSO_ATESTADOS AT inner join Cpe_Saude_Ocupacional SO on at.Id_Ocorrencia = so.Id_Ocorrencia and So.Pcmso_Matricula = '" + matricula.ToString() + "' AND at.Id_Ocorrencia = '" + idOcorrencia.ToString() + "') AND H.Matricula = '" + matricula.ToString() + "' ORDER BY Last_Updt_Dt DESC ")
    
    if valor == 0:
        return "erro"
    else:
        return "ok"

def ValidaPermissaoPorArea(codAreaCliente, codAreaValida):

    resultado = 'Erro'

    if OrdemServico.Cliente.Orgao.Sigla == codAreaValida:
        resultado = 'Ok'
    else:
        areas = OrdemServico.Cliente.Orgao.ObtemSubOrgaos(True)

        for area in areas:
            if area.Ativo == True:
                if (area.Sigla == codAreaValida):
                    resultado = 'Ok'

        if resultado == 'Erro':
            areasPai = OrdemServico.Cliente.Orgao.ObtemOrgaosPais()

            for areaPai in areasPai:
                if areaPai.Ativo == True:
                    if (areaPai.Sigla == codAreaValida):
                        resultado = 'Ok'

    return resultado

def VerificaTipo(opcao):
    if opcao == "Inclusão na Fila de Espera do Estacionamento" or opcao == "Solicitar Posição na Fila de Espera":
        return "Inclusão na Fila de Espera do Estacionamento ou Solicitar Posição na Fila de Espera"
    elif opcao == "Inclusão na Fila de Espera do Estacionamento" or opcao == "Solicitar Posição na Fila de Espera":
        return "Inclusão na Fila de Espera do Estacionamento ou Solicitar Posição na Fila de Espera"
    elif opcao == "Atualização de Cadastro do Estacionamento" or opcao == "Desistência da Fila de Espera do Estacionamento":
        return "Atualização de Cadastro do Estacionamento ou Desistência da Fila de Espera do Estacionamento"
    else:
        return opcao

