def listarSolicitacoesNotificacao():
    try:
        result_table2 = DB.ExecuteDataTable("SELECT OCORRENCIA.NUMERO, OCORRENCIA.ASSUNTO, OCORRENCIA.SITUACAO, OCORRENCIA.DATA_HORA_ULT_ATUA, CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO, OCORRENCIA.DATA_HORA_SOL, CPE_CSC.OBJETO_CONTRATO, CPE_CSC.CSC_DATA_FIM, CPE_CSC.CSC_DGCO, CPE_CSC.OBSERVACAO, CP_ORDEM_SERVICO.NOME_FORNECEDOR, ORDEM_SERVICO.DESCRICAO_DETALHADA, PESSOA.NOME AS FISCAL_DE_SERVICO, PESSOA1.NOME AS FISCAL_ADM_DO_CONTRATO, PESSOA2.NOME AS GESTOR_DO_CONTRATO, OCORRENCIA.ID_OCORRENCIA, PESSOA3.NOME AS RESPONSAVEL, PESSOA3.USUARIO_REDE AS USUARIO_RESPONSAVEL, CLASSE_SUB_PROCESSO.SIGLA, CPE_CONTRATOS02.CLAUSULA_CONTRATUAL_DESCUMPRIDA FROM OCORRENCIA LEFT JOIN CLASSE_SUB_PROCESSO ON CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO = OCORRENCIA.ID_CLASSE_SUB_PROC_INI LEFT JOIN CPE_CSC ON OCORRENCIA.ID_OCORRENCIA = CPE_CSC.ID_OCORRENCIA LEFT JOIN CP_ORDEM_SERVICO ON OCORRENCIA.ID_OCORRENCIA = CP_ORDEM_SERVICO.ID_OCORRENCIA LEFT JOIN ORDEM_SERVICO ON OCORRENCIA.ID_OCORRENCIA = ORDEM_SERVICO.ID_OCORRENCIA LEFT JOIN PESSOA ON PESSOA.ID_PESSOA = CPE_CSC.FISCAL_DE_SERVICO LEFT JOIN PESSOA PESSOA1 ON PESSOA1.ID_PESSOA = CPE_CSC.FISCAL_ADM_DO_CONTRATO LEFT JOIN PESSOA PESSOA2 ON PESSOA2.ID_PESSOA = CPE_CSC.GESTOR_DO_CONTRATO LEFT JOIN PESSOA PESSOA3 ON PESSOA3.ID_PESSOA = OCORRENCIA.ID_RESPONSAVEL LEFT JOIN CPE_CONTRATOS02 ON OCORRENCIA.ID_OCORRENCIA = CPE_CONTRATOS02.ID_OCORRENCIA WHERE (CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO IN (600) OR CLASSE_SUB_PROCESSO.SIGLA IN ('NOTIFICAFORNECEDORADITAMENTO2', 'NOTIFICACOESFORNECEDOR'))")
        
        json_data = JsonConvert.SerializeObject(result_table2)
        return json_data
    except Exception as e:
        return "Erro ao executar a consulta: " + str(e)


