        result_table2 = DB.ExecuteDataTable("Select OCORRENCIA.ID_OCORRENCIA, OCORRENCIA.ASSUNTO, OCORRENCIA.DATA_HORA_SOL, OCORRENCIA.ID_CLASSE_SUB_PROC_INI, OCORRENCIA.SITUACAO, OCORRENCIA.NUMERO, OCORRENCIA.DATA_HORA_ULT_ATUA, CPE_CSC.BANCO_NOME, CPE_CSC.AGENCIA_NUMERO, CPE_CSC.CSC_DIGITO_AGENCIA, CPE_CSC.CONTA_CORRENTE_NUMERO, CPE_CSC.CSC_CPF, CPE_CONTRATOS.OBS2, CP_ORDEM_SERVICO.NOME_FORNECEDOR, CP_ORDEM_SERVICO.CNPJ_FORNECEDOR, CPE_CONTRATOS.OBS3, PESSOA.NOME As RESPONSAVEL, PESSOA.USUARIO_REDE As USUARIO_RESPONSAVEL, CLASSE_SUB_PROCESSO.SIGLA From OCORRENCIA Left Join CPE_CSC On OCORRENCIA.ID_OCORRENCIA = CPE_CSC.ID_OCORRENCIA Left Join CPE_CONTRATOS On OCORRENCIA.ID_OCORRENCIA = CPE_CONTRATOS.ID_OCORRENCIA Left Join CP_ORDEM_SERVICO On OCORRENCIA.ID_OCORRENCIA = CP_ORDEM_SERVICO.ID_OCORRENCIA Left Join PESSOA On PESSOA.ID_PESSOA = OCORRENCIA.ID_RESPONSAVEL Left Join CLASSE_SUB_PROCESSO On OCORRENCIA.ID_CLASSE_SUB_PROC_INI = CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO Where (OCORRENCIA.ID_CLASSE_SUB_PROC_INI In (357) Or CLASSE_SUB_PROCESSO.SIGLA In ('ALTERARDADOSBANCARIOS', 'AUTORIZARALTDADOSBANC')) And OCORRENCIA.NUMERO = '"+str(numeroOs)+"'")
        
