        result_table2 = DB.ExecuteDataTable("Select OCORRENCIA.ASSUNTO, OCORRENCIA.DATA_HORA_SOL, OCORRENCIA.ID_CLASSE_SUB_PROC_INI, OCORRENCIA.NUMERO, OCORRENCIA.SITUACAO, OCORRENCIA.ID_OCORRENCIA, OCORRENCIA.DATA_HORA_ULT_ATUA, CP_ORDEM_SERVICO.NOME_FORNECEDOR, NVL(CPE_FINANCEIRO.DGCO_BB, CPE_CSC.CSC_DGCO) As CSC_DGCO, PESSOA.NOME As RESPONSAVEL, PESSOA.USUARIO_REDE As USUARIO_RESPONSAVEL, CPE_CSC.SIM_NAO3 As COMISSAO, CPE_CSC.OBS21 As OBJETO, PESSOA1.NOME As ANALISTA_TITULAR, CPE_CONTRATOS02.MATRICULA_ANA_TITU As MATRICULA_TITULAR, PESSOA2.NOME As ANALISTA_SUPLENTE, CPE_CONTRATOS02.MATRICULA_ANA_SUP As MATRICULA_SUPLENTE, CLASSE_SUB_PROCESSO.SIGLA From OCORRENCIA Left Join ORDEM_SERVICO On OCORRENCIA.ID_OCORRENCIA = ORDEM_SERVICO.ID_OCORRENCIA Left Join CP_ORDEM_SERVICO On ORDEM_SERVICO.ID_OCORRENCIA = CP_ORDEM_SERVICO.ID_OCORRENCIA Left Join CPE_CSC On OCORRENCIA.ID_OCORRENCIA = CPE_CSC.ID_OCORRENCIA Left Join PESSOA On PESSOA.ID_PESSOA = OCORRENCIA.ID_RESPONSAVEL Left Join CPE_FINANCEIRO On OCORRENCIA.ID_OCORRENCIA = CPE_FINANCEIRO.ID_OCORRENCIA Left Join CPE_CONTRATOS02 On OCORRENCIA.ID_OCORRENCIA = CPE_CONTRATOS02.ID_OCORRENCIA Left Join PESSOA PESSOA1 On PESSOA1.ID_PESSOA = CPE_CONTRATOS02.ANALISTA_CONTRATO_TITU Left Join CLASSE_SUB_PROCESSO On OCORRENCIA.ID_CLASSE_SUB_PROC_INI = CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO Left Join PESSOA PESSOA2 On PESSOA2.ID_PESSOA = CPE_CONTRATOS02.ANALISTA_CONTRATO_SUP Where (OCORRENCIA.ID_CLASSE_SUB_PROC_INI In (625) Or CLASSE_SUB_PROCESSO.SIGLA In ('ONBOARD'))")
        
        json_data = JsonConvert.SerializeObject(result_table2)
        return json_data
    except Exception as e:
        return "Erro ao executar a consulta: " + str(e)


