def enviaDadosGestoresUor():
    try:
        result_table2 = DB.ExecuteDataTable("SELECT MAX(matricula_sup_nivel1) AS MATRICULA_GESTOR, f.numero_subcr_nivel1 AS NUMERO, MAX(f.descricao_subcr_nivel1) AS DESCRICAO, MAX(c.scr_sigla) AS SIGLA FROM CAD_FUNCIONARIO_V F Left Join cob_gl_centro c ON c.scr = f.numero_subcr_nivel1 WHERE f.matricula_sup_nivel1 != ' ' GROUP BY f.numero_subcr_nivel1")
        
        
        json_data = JsonConvert.SerializeObject(result_table2)
        return json_data
    except Exception as e:
        return "Erro ao executar a consulta: " + str(e)




def enviaDadosAnalisePB(matriculaCondutor, situacao):
    try:
        if matriculaCondutor != "0":
            if situacao == "todos":
                result_table2 = DB.ExecuteDataTable("Select OCORRENCIA.ASSUNTO, OCORRENCIA.NUMERO, OCORRENCIA.SITUACAO, ORDEM_SERVICO.DESCRICAO_DETALHADA, PESSOA.NOME, CP_PESSOA.MATRICULA From OCORRENCIA Left Join CLASSE_SUB_PROCESSO On OCORRENCIA.ID_CLASSE_SUB_PROC = CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO Left Join ORDEM_SERVICO On OCORRENCIA.ID_OCORRENCIA = ORDEM_SERVICO.ID_OCORRENCIA Left Join PESSOA On PESSOA.ID_PESSOA = OCORRENCIA.ID_CLIENTE Left Join CP_PESSOA On PESSOA.ID_PESSOA = CP_PESSOA.ID_PESSOA Where CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO = 425 And CP_PESSOA.MATRICULA = '"+matriculaCondutor+"' Order By OCORRENCIA.NUMERO")
            else:
                result_table2 = DB.ExecuteDataTable("Select OCORRENCIA.ASSUNTO, OCORRENCIA.NUMERO, OCORRENCIA.SITUACAO, ORDEM_SERVICO.DESCRICAO_DETALHADA, PESSOA.NOME, CP_PESSOA.MATRICULA From OCORRENCIA Left Join CLASSE_SUB_PROCESSO On OCORRENCIA.ID_CLASSE_SUB_PROC = CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO Left Join ORDEM_SERVICO On OCORRENCIA.ID_OCORRENCIA = ORDEM_SERVICO.ID_OCORRENCIA Left Join PESSOA On PESSOA.ID_PESSOA = OCORRENCIA.ID_CLIENTE Left Join CP_PESSOA On PESSOA.ID_PESSOA = CP_PESSOA.ID_PESSOA Where CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO = 425 And CP_PESSOA.MATRICULA = '"+matriculaCondutor+"' And OCORRENCIA.SITUACAO = '"+situacao+"' Order By OCORRENCIA.NUMERO")    
        else:
            if situacao == "todos":
                result_table2 = DB.ExecuteDataTable("Select OCORRENCIA.ASSUNTO, OCORRENCIA.NUMERO, OCORRENCIA.SITUACAO, ORDEM_SERVICO.DESCRICAO_DETALHADA, PESSOA.NOME, CP_PESSOA.MATRICULA From OCORRENCIA Left Join CLASSE_SUB_PROCESSO On OCORRENCIA.ID_CLASSE_SUB_PROC = CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO Left Join ORDEM_SERVICO On OCORRENCIA.ID_OCORRENCIA = ORDEM_SERVICO.ID_OCORRENCIA Left Join PESSOA On PESSOA.ID_PESSOA = OCORRENCIA.ID_CLIENTE Left Join CP_PESSOA On PESSOA.ID_PESSOA = CP_PESSOA.ID_PESSOA Where CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO = 425 Order By OCORRENCIA.NUMERO")
            else:
                result_table2 = DB.ExecuteDataTable("Select OCORRENCIA.ASSUNTO, OCORRENCIA.NUMERO, OCORRENCIA.SITUACAO, ORDEM_SERVICO.DESCRICAO_DETALHADA, PESSOA.NOME, CP_PESSOA.MATRICULA From OCORRENCIA Left Join CLASSE_SUB_PROCESSO On OCORRENCIA.ID_CLASSE_SUB_PROC = CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO Left Join ORDEM_SERVICO On OCORRENCIA.ID_OCORRENCIA = ORDEM_SERVICO.ID_OCORRENCIA Left Join PESSOA On PESSOA.ID_PESSOA = OCORRENCIA.ID_CLIENTE Left Join CP_PESSOA On PESSOA.ID_PESSOA = CP_PESSOA.ID_PESSOA Where CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO = 425 And OCORRENCIA.SITUACAO = '"+situacao+"' Order By OCORRENCIA.NUMERO")
        
        json_data = JsonConvert.SerializeObject(result_table2)
        return json_data
    except Exception as e:
        return "Erro ao executar a consulta: " + str(e)



