def listarProcessosAdministrativos():
    try:
        result_table2 = DB.ExecuteDataTable("SELECT OCORRENCIA.ID_OCORRENCIA, OCORRENCIA.ASSUNTO, OCORRENCIA.DATA_HORA_SOL, OCORRENCIA.DATA_HORA_ULT_ATUA, OCORRENCIA.DATA_HORA_FIM_REAL AS DATA_HORA_FIM_SOL, OCORRENCIA.ID_CLASSE_SUB_PROC_INI, OCORRENCIA.SITUACAO, OCORRENCIA.NUMERO, CPE_HOMOLOGACAO.TIP_SOLDR, ORDEM_SERVICO.DESCRICAO_DETALHADA, PESSOA.NOME AS RESPONSAVEL, PESSOA.USUARIO_REDE AS USUARIO_RESPONSAVEL, CP_ORDEM_SERVICO.NOME_FORNECEDOR, CPE_CSC.CSC_DGCO, CLASSE_SUB_PROCESSO.SIGLA, CPE_CSC.CSC_DATA_FIM AS FIM_VIGENCIA, CPE_CSC.SIM_NAO1 AS COMISSAO, CPE_CSC.OBSERVACAO, CPE_CSC.OBJETO_CONTRATO, PESSOA1.NOME AS GESTOR, PESSOA2.NOME AS FISCAL_ADM, PESSOA3.NOME AS FISCAL_SERVICO, CASE WHEN OCORRENCIA.SITUACAO = 'Aberto' THEN FLOOR(SYSDATE - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || FLOOR(MOD((SYSDATE - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' ELSE FLOOR(OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || FLOOR(MOD((OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' END AS TEMPO FROM OCORRENCIA LEFT JOIN CPE_CSC ON OCORRENCIA.ID_OCORRENCIA = CPE_CSC.ID_OCORRENCIA LEFT JOIN CPE_HOMOLOGACAO ON OCORRENCIA.ID_OCORRENCIA = CPE_HOMOLOGACAO.ID_OCORRENCIA LEFT JOIN ORDEM_SERVICO ON OCORRENCIA.ID_OCORRENCIA = ORDEM_SERVICO.ID_OCORRENCIA LEFT JOIN PESSOA ON OCORRENCIA.ID_RESPONSAVEL = PESSOA.ID_PESSOA LEFT JOIN CP_ORDEM_SERVICO ON OCORRENCIA.ID_OCORRENCIA = CP_ORDEM_SERVICO.ID_OCORRENCIA LEFT JOIN CLASSE_SUB_PROCESSO ON OCORRENCIA.ID_CLASSE_SUB_PROC_INI = CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO LEFT JOIN PESSOA PESSOA1 ON CPE_CSC.GESTOR_DO_CONTRATO = PESSOA1.ID_PESSOA LEFT JOIN PESSOA PESSOA2 ON CPE_CSC.FISCAL_ADM_DO_CONTRATO = PESSOA2.ID_PESSOA LEFT JOIN PESSOA PESSOA3 ON CPE_CSC.FISCAL_DE_SERVICO = PESSOA3.ID_PESSOA WHERE (OCORRENCIA.ID_CLASSE_SUB_PROC_INI IN (598) OR CLASSE_SUB_PROCESSO.SIGLA IN ('PROCESSADM'))")
        
