# E N C E R R A M E N T O   C O N T R A T U A L
def listarEncerramentosContratuais():
    try:
        result_table2 = DB.ExecuteDataTable("Select OCORRENCIA.NUMERO, OCORRENCIA.ASSUNTO, OCORRENCIA.SITUACAO, OCORRENCIA.DATA_HORA_ULT_ATUA, CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO, OCORRENCIA.DATA_HORA_SOL, OCORRENCIA.DATA_HORA_FIM_REAL As DATA_HORA_FIM_SOL, CPE_CSC.OBJETO_CONTRATO, CPE_CSC.CSC_DATA_FIM, CPE_CSC.CSC_DGCO, CPE_CSC.OBSERVACAO, CP_ORDEM_SERVICO.NOME_FORNECEDOR, ORDEM_SERVICO.DESCRICAO_DETALHADA, PESSOA.NOME As FISCAL_DE_SERVICO, PESSOA1.NOME As FISCAL_ADM_DO_CONTRATO, PESSOA2.NOME As GESTOR_DO_CONTRATO, OCORRENCIA.ID_OCORRENCIA, PESSOA3.NOME As RESPONSAVEL, PESSOA3.ID_PESSOA, PESSOA3.USUARIO_REDE As USUARIO_RESPONSAVEL, Case When OCORRENCIA.SITUACAO = 'Aberto' Then Floor(SysDate - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || Floor(Mod((SysDate - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' Else Floor(OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || Floor(Mod((OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' End As TEMPO, CPE_CSC.DATA_APROVACAO_FISCAL_ADM, CPE_CSC.DATA_APROVACAO_FISCAL_SERV, CPE_CSC.DATA_APROVACAO_GESTOR From OCORRENCIA Left Join CLASSE_SUB_PROCESSO On CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO = OCORRENCIA.ID_CLASSE_SUB_PROC_INI Left Join CPE_CSC On OCORRENCIA.ID_OCORRENCIA = CPE_CSC.ID_OCORRENCIA Left Join CP_ORDEM_SERVICO On OCORRENCIA.ID_OCORRENCIA = CP_ORDEM_SERVICO.ID_OCORRENCIA Left Join ORDEM_SERVICO On OCORRENCIA.ID_OCORRENCIA = ORDEM_SERVICO.ID_OCORRENCIA Left Join PESSOA On PESSOA.ID_PESSOA = CPE_CSC.FISCAL_DE_SERVICO Left Join PESSOA PESSOA1 On PESSOA1.ID_PESSOA = CPE_CSC.FISCAL_ADM_DO_CONTRATO Left Join PESSOA PESSOA2 On PESSOA2.ID_PESSOA = CPE_CSC.GESTOR_DO_CONTRATO Left Join PESSOA PESSOA3 On PESSOA3.ID_PESSOA = OCORRENCIA.ID_RESPONSAVEL Where (CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO In (536, 327) Or CLASSE_SUB_PROCESSO.SIGLA In ('AVSENCERRACONTRATO', 'AVISOENCERRACONT', 'ENCERRAMENTODECONTRATO'))")
        
        json_data = JsonConvert.SerializeObject(result_table2)
        return json_data
    except Exception as e:
        return "Erro ao executar a consulta: " + str(e)


def buscarDetalhesEncerramentoContratual(numeroOs):
    try:
        result_table2 = DB.ExecuteDataTable("Select OCORRENCIA.NUMERO, OCORRENCIA.ASSUNTO, OCORRENCIA.SITUACAO, OCORRENCIA.DATA_HORA_ULT_ATUA, CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO, OCORRENCIA.DATA_HORA_SOL, OCORRENCIA.DATA_HORA_FIM_REAL As DATA_HORA_FIM_SOL, CPE_CSC.OBJETO_CONTRATO, CPE_CSC.CSC_DATA_FIM, CPE_CSC.CSC_DGCO, CPE_CSC.OBSERVACAO, CP_ORDEM_SERVICO.NOME_FORNECEDOR, ORDEM_SERVICO.DESCRICAO_DETALHADA, PESSOA.NOME As FISCAL_DE_SERVICO, PESSOA1.NOME As FISCAL_ADM_DO_CONTRATO, PESSOA2.NOME As GESTOR_DO_CONTRATO, OCORRENCIA.ID_OCORRENCIA, PESSOA3.NOME As RESPONSAVEL, PESSOA3.ID_PESSOA, PESSOA3.USUARIO_REDE As USUARIO_RESPONSAVEL, Case When OCORRENCIA.SITUACAO = 'Aberto' Then Floor(SysDate - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || Floor(Mod((SysDate - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' Else Floor(OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || Floor(Mod((OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' End As TEMPO, CPE_CSC.DATA_APROVACAO_FISCAL_ADM, CPE_CSC.DATA_APROVACAO_FISCAL_SERV, CPE_CSC.DATA_APROVACAO_GESTOR From OCORRENCIA Left Join CLASSE_SUB_PROCESSO On CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO = OCORRENCIA.ID_CLASSE_SUB_PROC_INI Left Join CPE_CSC On OCORRENCIA.ID_OCORRENCIA = CPE_CSC.ID_OCORRENCIA Left Join CP_ORDEM_SERVICO On OCORRENCIA.ID_OCORRENCIA = CP_ORDEM_SERVICO.ID_OCORRENCIA Left Join ORDEM_SERVICO On OCORRENCIA.ID_OCORRENCIA = ORDEM_SERVICO.ID_OCORRENCIA Left Join PESSOA On PESSOA.ID_PESSOA = CPE_CSC.FISCAL_DE_SERVICO Left Join PESSOA PESSOA1 On PESSOA1.ID_PESSOA = CPE_CSC.FISCAL_ADM_DO_CONTRATO Left Join PESSOA PESSOA2 On PESSOA2.ID_PESSOA = CPE_CSC.GESTOR_DO_CONTRATO Left Join PESSOA PESSOA3 On PESSOA3.ID_PESSOA = OCORRENCIA.ID_RESPONSAVEL Where (CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO In (536, 327) Or CLASSE_SUB_PROCESSO.SIGLA In ('AVSENCERRACONTRATO', 'AVISOENCERRACONT', 'ENCERRAMENTODECONTRATO')) And OCORRENCIA.NUMERO = '"+str(numeroOs)+"'")
        
        json_data = JsonConvert.SerializeObject(result_table2)
        return json_data
    except Exception as e:
        return "Erro ao executar a consulta: " + str(e)



