def listarOnBoard():
    try:
        result_table2 = DB.ExecuteDataTable("SELECT OCORRENCIA.ASSUNTO, OCORRENCIA.DATA_HORA_SOL, OCORRENCIA.ID_CLASSE_SUB_PROC_INI, OCORRENCIA.NUMERO, OCORRENCIA.SITUACAO, OCORRENCIA.ID_OCORRENCIA, OCORRENCIA.DATA_HORA_ULT_ATUA, OCORRENCIA.DATA_HORA_FIM_REAL AS DATA_HORA_FIM_SOL, CP_ORDEM_SERVICO.NOME_FORNECEDOR, NVL(CPE_FINANCEIRO.DGCO_BB, CPE_CSC.CSC_DGCO) AS CSC_DGCO, PESSOA.NOME AS RESPONSAVEL, PESSOA.USUARIO_REDE AS USUARIO_RESPONSAVEL, CPE_CSC.SIM_NAO3 AS COMISSAO, CPE_CSC.OBS21 AS OBJETO, PESSOA1.NOME AS ANALISTA_TITULAR, CPE_CONTRATOS02.MATRICULA_ANA_TITU AS MATRICULA_TITULAR, PESSOA2.NOME AS ANALISTA_SUPLENTE, CPE_CONTRATOS02.MATRICULA_ANA_SUP AS MATRICULA_SUPLENTE, CLASSE_SUB_PROCESSO.SIGLA, CASE WHEN OCORRENCIA.SITUACAO = 'Aberto' THEN FLOOR(SYSDATE - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || FLOOR(MOD((SYSDATE - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' ELSE FLOOR(OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || FLOOR(MOD((OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' END AS TEMPO FROM OCORRENCIA LEFT JOIN ORDEM_SERVICO ON OCORRENCIA.ID_OCORRENCIA = ORDEM_SERVICO.ID_OCORRENCIA LEFT JOIN CP_ORDEM_SERVICO ON ORDEM_SERVICO.ID_OCORRENCIA = CP_ORDEM_SERVICO.ID_OCORRENCIA LEFT JOIN CPE_CSC ON OCORRENCIA.ID_OCORRENCIA = CPE_CSC.ID_OCORRENCIA LEFT JOIN PESSOA ON PESSOA.ID_PESSOA = OCORRENCIA.ID_RESPONSAVEL LEFT JOIN CPE_FINANCEIRO ON OCORRENCIA.ID_OCORRENCIA = CPE_FINANCEIRO.ID_OCORRENCIA LEFT JOIN CPE_CONTRATOS02 ON OCORRENCIA.ID_OCORRENCIA = CPE_CONTRATOS02.ID_OCORRENCIA LEFT JOIN PESSOA PESSOA1 ON PESSOA1.ID_PESSOA = CPE_CONTRATOS02.ANALISTA_CONTRATO_TITU LEFT JOIN CLASSE_SUB_PROCESSO ON OCORRENCIA.ID_CLASSE_SUB_PROC_INI = CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO LEFT JOIN PESSOA PESSOA2 ON PESSOA2.ID_PESSOA = CPE_CONTRATOS02.ANALISTA_CONTRATO_SUP WHERE (OCORRENCIA.ID_CLASSE_SUB_PROC_INI IN (625) OR CLASSE_SUB_PROCESSO.SIGLA IN ('ONBOARD'))")
        
        json_data = JsonConvert.SerializeObject(result_table2)
        return json_data
    except Exception as e:
        return "Erro ao executar a consulta: " + str(e)


