def buscarOCInserirDocumentosContratuaisPorOs(numeroOs):
    try:
        result_table2 = DB.ExecuteDataTable("Select Unique CLASSE_SUB_PROCESSO.DESCRICAO, CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO, CLASSE_SUB_PROCESSO.SIGLA, OCORRENCIA.ID_CLASSE_SUB_PROC_INI, OCORRENCIA.ID_OCORRENCIA As IDENTIFICADOR, CPE_FINANCEIRO.DGCO_BB As CSC_DGCO, CP_ORDEM_SERVICO.NUMERO_OC, CPE_CSC.NUMERO_RC, CPE_CSC.TIPO_SOLICITACAO_OC As TIPO_SOLICITACAO_OC, CPE_CSC.TIPO_OC_CSC As TIPO_OC, CPE_CONTRATOS.MODALIDADE_DE_CONTRATACAO, CPE_CONTRATOS.OBS5 As DESCRICAO_DETALHADA, PESSOA.NOME As RESPONSAVEL_TRATAMENTO, OCORRENCIA.SITUACAO, OCORRENCIA.NUMERO, OCORRENCIA.ASSUNTO, OCORRENCIA.DATA_HORA_SOL As DATA_HORA_SOL, OCORRENCIA.DATA_HORA_FIM_REAL As DATA_HORA_FIM_SOL, Case When OCORRENCIA.SITUACAO = 'Aberto' Then Floor(SysDate - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || Floor(Mod((SysDate - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' Else Floor(OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || Floor(Mod((OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' End As TEMPO From OCORRENCIA Left Join CLASSE_SUB_PROCESSO On OCORRENCIA.ID_CLASSE_SUB_PROC_INI = CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO Left Join CPE_FINANCEIRO On OCORRENCIA.ID_OCORRENCIA = CPE_FINANCEIRO.ID_OCORRENCIA Left Join CP_ORDEM_SERVICO On OCORRENCIA.ID_OCORRENCIA = CP_ORDEM_SERVICO.ID_OCORRENCIA Left Join CPE_CSC On OCORRENCIA.ID_OCORRENCIA = CPE_CSC.ID_OCORRENCIA Left Join CPE_CONTRATOS On OCORRENCIA.ID_OCORRENCIA = CPE_CONTRATOS.ID_OCORRENCIA Left Join PESSOA On PESSOA.ID_PESSOA = CP_ORDEM_SERVICO.FAVORECIDO_TODOS Where (CLASSE_SUB_PROCESSO.SIGLA In ('ORDEMDECOMRAS') Or OCORRENCIA.ID_CLASSE_SUB_PROC_INI In (130)) AND OCORRENCIA.NUMERO LIKE '%{}%'".format(numeroOs))
        
        json_data = JsonConvert.SerializeObject(result_table2)
        return json_data
    except Exception as e:
        return "Erro ao executar a consulta: " + str(e)
        
        
        
        
        
def buscarFiscoTributaInserirDocumentosContratuaisPorOs(numeroOs):
    try:
        result_table2 = DB.ExecuteDataTable("Select Unique CLASSE_SUB_PROCESSO.DESCRICAO, CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO, CLASSE_SUB_PROCESSO.SIGLA, OCORRENCIA.ID_CLASSE_SUB_PROC_INI, OCORRENCIA.ID_OCORRENCIA As IDENTIFICADOR, OCORRENCIA.SITUACAO, OCORRENCIA.NUMERO, OCORRENCIA.ASSUNTO, OCORRENCIA.DATA_HORA_SOL As DATA_HORA_SOL, OCORRENCIA.DATA_HORA_FIM_REAL As DATA_HORA_FIM_SOL, Case When OCORRENCIA.SITUACAO = 'Aberto' Then Floor(SysDate - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || Floor(Mod((SysDate - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' Else Floor(OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || Floor(Mod((OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' End As TEMPO, PESSOA.NOME As RESPONSAVEL From OCORRENCIA Left Join CLASSE_SUB_PROCESSO On OCORRENCIA.ID_CLASSE_SUB_PROC_INI = CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO Inner Join PESSOA On OCORRENCIA.ID_RESPONSAVEL = PESSOA.ID_PESSOA Where (CLASSE_SUB_PROCESSO.SIGLA In ('CONFISCOTRIBUTARIA') Or OCORRENCIA.ID_CLASSE_SUB_PROC_INI In (71)) AND OCORRENCIA.NUMERO LIKE '%{}%'".format(numeroOs))
        
