def listarChamadosAbertos(): ###Trocar os IDS PARA OS CHAMADOS DA DICOC
    try:
        result_table2 = DB.ExecuteDataTable("Select OCORRENCIA.NUMERO, OCORRENCIA.ASSUNTO, OCORRENCIA.SITUACAO, OCORRENCIA.DATA_HORA_SOL, OCORRENCIA.DATA_HORA_ULT_ATUA, PESSOA.NOME As RESPONSAVEL, PESSOA.USUARIO_REDE, FLOOR(SYSDATE - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || FLOOR(MOD((SYSDATE - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' AS TEMPO_EM_ABERTO From OCORRENCIA Left Join ORDEM_SERVICO On OCORRENCIA.ID_OCORRENCIA = ORDEM_SERVICO.ID_OCORRENCIA Left Join CPE_FINANCEIRO On OCORRENCIA.ID_OCORRENCIA = CPE_FINANCEIRO.ID_OCORRENCIA Left Join CP_ORDEM_SERVICO On OCORRENCIA.ID_OCORRENCIA = CP_ORDEM_SERVICO.ID_OCORRENCIA Left Join PESSOA On PESSOA.ID_PESSOA = OCORRENCIA.ID_RESPONSAVEL Left Join CLASSE_SUB_PROCESSO On OCORRENCIA.ID_CLASSE_SUB_PROC_INI = CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO Where OCORRENCIA.SITUACAO = 'Aberto' And (CLASSE_SUB_PROCESSO.SIGLA In ('ASSINATURACONTRATOSADITIVOS', 'ACIONAATAASSINA', 'ATESTADOCAPACIDADE', 'CADCONTRAOKS', 'DESIGNACTRCLIENTE', 'DISTRATO', 'DISTRCLIENTES','ADITIVOSCLIENTES', 'PROCUNIFCONT', 'TERMOCONTRATOCLIENT') or OCORRENCIA.ID_CLASSE_SUB_PROC_INI In (336, 702, 513, 333, 528, 289, 715, 335, 272, 703)) Order By OCORRENCIA.DATA_HORA_SOL")
        json_data = JsonConvert.SerializeObject(result_table2)
        return json_data
    except Exception as e:
        return "Erro ao executar a consulta: " + str(e)

        

        

