def to_str(x):
    try:
        if x is None:
            return ""
        s = x.ToString()
        if s is None:
            return ""
        return s
    except:
        try:
            s = str(x)
            if s is None:
                return ""
            return s
        except:
            return ""


def is_null_or_empty(v):
    return to_str(v).strip() == ""


def to_int_safe(v, default=0):
    try:
        if v is None:
            return default
        s = to_str(v).strip()
        if s == "":
            return default
        return Convert.ToInt32(s)
    except:
        try:
            return int(str(v))
        except:
            return default


def to_decimal_safe(v, default=0.0):
    try:
        if v is None:
            return Convert.ToDecimal(default)
        s = to_str(v).strip().replace(',', '.')
        if s == "":
            return Convert.ToDecimal(default)
        return Convert.ToDecimal(s)
    except:
        try:
            return Convert.ToDecimal(default)
        except:
            return default


def safe_row_str(row, col):
    try:
        return to_str(row[col]).strip()
    except:
        return ""


def safe_row_int(row, col, default=0):
    try:
        return to_int_safe(row[col], default)
    except:
        return default


def ParseDateSafe(s):
    if not s:
        return None
    formatos = [
        "dd-MM-yyyy", "dd/MM/yyyy", "yyyy-MM-dd", "yyyy/MM/dd",
        "yyyy-MM-ddTHH:mm:ss", "yyyy-MM-ddTHH:mm:ssZ",
        "yyyy-MM-ddTHH:mm:ss.fff", "yyyy-MM-ddTHH:mm:ss.fffZ",
        "yyyy-MM-dd HH:mm:ss", "dd/MM/yyyy HH:mm:ss", "dd-MM-yyyy HH:mm:ss"
    ]
    txt = to_str(s).strip()
    if txt == "":
        return None
    for f in formatos:
        try:
            return DateTime.ParseExact(txt, f, None)
        except:
            pass
    try:
        return DateTime.Parse(txt)
    except:
        return None


def to_list(value):
    if value is None:
        return []
    try:
        if isinstance(value, str):
            return []
    except:
        pass
    try:
        if hasattr(value, "Rows"):
            return list(value.Rows)
    except:
        pass
    try:
        if hasattr(value, "ContainsKey"):
            return [value]
        if isinstance(value, dict):
            return [value]
    except:
        pass
    try:
        if isinstance(value, JArray):
            return [x for x in value]
    except:
        pass
    try:
        return list(value)
    except:
        return []


def get_prop(obj, keys, default=None):
    if obj is None:
        return default
    for k in keys:
        try:
            if isinstance(obj, JObject):
                tok = obj.GetValue(k)
                if tok is not None:
                    return tok
        except:
            pass
        try:
            val = obj[k]
            if val is not None:
                return val
        except:
            pass
    return default


def periodo_para_dias_uteis_no_mes(di, df, ano_, mes_):
    s = set()
    if di is None or df is None:
        return s
    ini_mes = DateTime(ano_, mes_, 1)
    fim_mes = DateTime(ano_, mes_, DateTime.DaysInMonth(ano_, mes_))
    ini = di if di > ini_mes else ini_mes
    fim = df if df < fim_mes else fim_mes
    if ini > fim:
        return s
    d = ini.Date
    while d <= fim.Date:
        if d.DayOfWeek != DayOfWeek.Saturday and d.DayOfWeek != DayOfWeek.Sunday:
            s.add(d.Date)
        d = d.AddDays(1)
    return s


def set_to_sorted_dates(date_set):
    arr = list(date_set)
    arr.sort()
    return arr


def set_to_sorted_str_list(date_set):
    arr = []
    try:
        datas = list(date_set)
        datas.sort()
        for d in datas:
            try:
                arr.append(d.ToString("dd/MM/yyyy"))
            except:
                arr.append(to_str(d))
    except:
        pass
    return arr


def chunk_text_lines(lines, max_len):
    parts = []
    current = ""
    for line in lines:
        candidate = current + line + "\n"
        if len(candidate) > max_len and current != "":
            parts.append(current.rstrip())
            current = line + "\n"
        else:
            current = candidate
    if current.strip() != "":
        parts.append(current.rstrip())
    return parts

